#include <stdio.h>
int main(void) {
    int w[] = {2, 3}, v[] = {3, 4};
    int dp[3][5] = {0};
    for (int i = 1; i <= 2; i++)
        for (int c = 0; c <= 4; c++) {
            dp[i][c] = dp[i-1][c];
            if (w[i-1] <= c && dp[i-1][c-w[i-1]] + v[i-1] > dp[i][c])
                dp[i][c] = dp[i-1][c-w[i-1]] + v[i-1];
        }
    printf("%d\n", dp[2][4]);
    return 0;
}

#include <stdio.h>
int main(void) {
    char *x = "ABCB", *y = "BDCB";
    int m = 4, n = 4, dp[5][5] = {0};
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            dp[i][j] = (x[i-1] == y[j-1]) ? dp[i-1][j-1] + 1
                       : (dp[i-1][j] > dp[i][j-1] ? dp[i-1][j] : dp[i][j-1]);
    printf("%d\n", dp[m][n]);
    return 0;
}

